INSERT INTO incidents_incidentreport (id, child_id, reported_by_id, incident_type, description, occurred_on, occured_at, severity, is_resolved, created_at) VALUES
  (1, 21, 2, 'S', 'Minor collision with another child during free play. No injury. Both children consoled and redirected.', '2026-04-06', '14:30', 'M', TRUE, CURRENT_TIMESTAMP),
  (2, 24, 3, 'S', 'Child tripped on playground equipment and scraped a knee. Area cleaned and bandaged. Ice pack applied. Guardian notified at pickup.', '2026-03-26', '15:45', 'M', TRUE, CURRENT_TIMESTAMP),
  (3, 33, 3, 'M', 'Child reported feeling dizzy during circle time. Moved to rest area, given water. Temperature normal. Monitored with no further symptoms.', '2026-03-24', '14:30', 'M', TRUE, CURRENT_TIMESTAMP),
  (4, 37, 4, 'M', 'Child exhibited an allergic reaction (hives) after outdoor play. Antihistamine administered per care plan. Guardian called immediately. Symptoms resolved within 30 minutes.', '2026-03-17', '08:00', 'MD', TRUE, CURRENT_TIMESTAMP),
  (5, 38, 4, 'S', 'Child fell from the bottom rung of the climber. Bumped forehead; small bruise. Ice applied, monitored for 1 hour. Guardian notified by phone.', '2026-04-15', '09:00', 'MD', TRUE, CURRENT_TIMESTAMP),
  (6, 51, 3, 'M', 'Child reported feeling dizzy during circle time. Moved to rest area, given water. Temperature normal. Monitored with no further symptoms.', '2026-05-08', '09:00', 'M', TRUE, CURRENT_TIMESTAMP),
  (7, 69, 5, 'S', 'Minor collision with another child during free play. No injury. Both children consoled and redirected.', '2026-05-08', '12:30', 'M', TRUE, CURRENT_TIMESTAMP);
INSERT INTO communication_announcement (id, title, message, created_by_id, created_at, updated_at) VALUES
  (1, 'Summer Hours Begin June 2', 'Starting Monday June 2, all sites operate on summer hours: 6:30 AM - 6:00 PM. Please update your schedules.', 2, '2026-05-01 09:00:00-04', '2026-05-01 09:00:00-04'),
  (2, 'Staff Development Day - May 23', 'All sites will be CLOSED Friday May 23 for professional development. No childcare services available.', 2, '2026-05-05 08:00:00-04', '2026-05-05 08:00:00-04'),
  (3, 'New Allergy Policy', 'Per updated health-department guidance, all nut products are prohibited in classrooms. Review the food policy in your packet.', 2, '2026-04-15 10:30:00-04', '2026-04-16 14:00:00-04'),
  (4, 'Picture Day', 'Picture day is Wednesday May 28. Send children in their preferred outfit and a change of clothes.', 2, '2026-05-12 08:30:00-04', '2026-05-12 08:30:00-04'),
  (5, 'Field Trip Permission Forms Due', 'Permission forms for the June nature-center trip are due Friday May 30.', 2, '2026-05-13 09:15:00-04', '2026-05-13 09:15:00-04'),
  (6, 'Water Play Days Begin', 'Water play begins the week of June 9. Send labeled swimwear and towels.', 3, '2026-05-19 11:00:00-04', '2026-05-19 11:00:00-04'),
  (7, 'Updated Pickup Procedure', 'All pickup persons must present photo ID and know the pickup PIN.', 2, '2026-05-21 13:30:00-04', '2026-05-21 13:30:00-04'),
  (8, 'Juneteenth Closure', 'All facilities will be closed June 19 in observance of Juneteenth.', 2, '2026-06-02 09:30:00-04', '2026-06-02 09:30:00-04');
